import subprocess

def dur(f):
    return float(subprocess.run(['ffprobe','-v','error','-show_entries','format=duration','-of','default=nw=1:nk=1',f], capture_output=True, text=True).stdout.strip())

ranges = list(range(42))
trans = {6:7, 11:12, 13:14, 17:18, 20:21}
skip = set(trans.values())
t = 0.0
boundaries = {}
for i in ranges:
    if i in skip:
        continue
    if i in trans:
        f = f'clips_transitions/trans_{i:02d}_{trans[i]:02d}.mp4'
        d = dur(f)
        # crossfade starts at offset within this clip = dur_a - 0.4 where dur_a = seg duration
        segA = f'clips_composited/seg_{i:02d}.mp4'
        dA = dur(segA)
        offset_in_clip = dA - 0.4
        boundaries[i] = (t + offset_in_clip, t + offset_in_clip + 0.4)
        t += d
    else:
        f = f'clips_composited/seg_{i:02d}.mp4'
        t += dur(f)
print('total', t)
for k,v in boundaries.items():
    print(k, v)
